package com.aadil.ecommerce.dtos;import jakarta.validation.constraints.Email;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.Pattern;import jakarta.validation.constraints.Size;import lombok.Getter;import lombok.NoArgsConstructor;import lombok.Setter;@Getter@Setter@NoArgsConstructorpublic class BootStrapRequestDTO {    @NotBlank (message = "Name field should NOT be BLANK")    @Size(max = 50)    private String name;    @Email    @NotBlank (message = "Email field should NOT be BLANK")    private String email;    @NotBlank (message = "Password field should NOT be BLANK")    @Pattern(regexp = "^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{8,}$")    @Size (min = 8,max = 12,message = "Password should be at least 8 to 12 characters")    private String password;}